+    /* Deep copy. */
+    hash_dest.type = hash_src->type;
+    /* array of octets */
+    hash_dest.hash_bytes =
+        g_byte_array_new_take((guint8 *)g_memdup2(hash_src->hash_bytes->data,
+                                                  hash_src->hash_bytes->len),
+                              hash_src->hash_bytes->len);
+    return hash_dest;
+}
